import React, { useState, useEffect } from 'react';
import { getExamData, deleteUserExamData, updateExamData } from '../services/api'; // Import the delete and update functions

const ExamData = () => {
  const [examDataList, setExamDataList] = useState([]);
  const [filteredExamData, setFilteredExamData] = useState([]);
  const [errorMessage, setErrorMessage] = useState('');
  const [selectedFranchise, setSelectedFranchise] = useState(''); // For franchise selection
  const [editingExamId, setEditingExamId] = useState(null); // Track which exam is being edited
  const [editingData, setEditingData] = useState({
    name: '',
    examName: '',
    date: '',
    durationInMinutes: '',
    status: '',
  });

  useEffect(() => {
    const fetchExamData = async () => {
      try {
        const response = await getExamData();
        if (response && response.length > 0) {
          const allExamData = response.flatMap(franchise =>
            (franchise.examData || []).map(exam => ({
              franchiseId: franchise._id,
              franchiseName: franchise.name,
              location: franchise.location,
              name: exam.name,
              examName: exam.examName,
              date: exam.date ? new Date(exam.date).toISOString().split('T')[0] : '', // Normalize date
              duration: exam.durationInMinutes,
              status: exam.status,
              examId: exam._id,
            }))
          );
          setExamDataList(allExamData);
          setFilteredExamData(allExamData);
        } else {
          setErrorMessage('No exam data available for your franchises.');
        }
      } catch (error) {
        console.error('Error fetching exam data:', error);
        setErrorMessage('Unable to retrieve exam data. Please try again later.');
      }
    };

    fetchExamData();
  }, []);

  // Handle franchise filter change
  const handleFranchiseChange = (e) => {
    const franchiseName = e.target.value;
    setSelectedFranchise(franchiseName);

    if (franchiseName === '') {
      setFilteredExamData(examDataList); // Show all data if no franchise is selected
    } else {
      const filteredData = examDataList.filter(exam => exam.franchiseName === franchiseName);
      setFilteredExamData(filteredData);
    }
  };

  // Get distinct franchise names for the dropdown filter
  const franchiseNames = [...new Set(examDataList.map(exam => exam.franchiseName))];

  // Delete exam data
  const handleDelete = async (examId, franchiseId) => {
    try {
      await deleteUserExamData(franchiseId, examId); // Delete via API
      setExamDataList(prevState => prevState.filter(exam => exam.examId !== examId)); // Remove from local state
      setFilteredExamData(prevState => prevState.filter(exam => exam.examId !== examId)); // Update filtered data
    } catch (error) {
      console.error('Error deleting exam data:', error);
      setErrorMessage('Unable to delete exam data. Please try again later.');
    }
  };

  // Handle edit functionality
  const handleEditClick = (exam) => {
    setEditingExamId(exam.examId); // Set the examId of the item being edited
    setEditingData({
      franchiseId: exam.franchiseId,
      name: exam.name,
      
      examName: exam.examName,
      date: exam.date,
      durationInMinutes: exam.duration,
      status: exam.status,
    });
  };

  // Handle change in form inputs during editing
  const handleChange = (e) => {
    const { name, value } = e.target;
    setEditingData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };


 

  // Save edited exam data
  const handleSave = async () => {
    try {
      // Log the current state of the data to be sent to the API
      console.log('Saving exam data with the following details:', editingData);
      
      // Ensure the date is formatted correctly
      const updatedExam = {
        ...editingData,
        date: new Date(editingData.date).toISOString().split('T')[0], // Ensure date is formatted correctly
      };
  
      // Log the updated data
      console.log('Formatted exam data to send:', updatedExam);
  
      const payload = { examData: [updatedExam] }; // Wrap data in array as expected by the API
      console.log('Payload being sent to API:', payload);
  
      // Call the API to update exam data
      await updateExamData(editingData.franchiseId, editingExamId, payload);
  
      // Update the exam data in state after successful update
      setExamDataList((prevState) =>
        prevState.map((examItem) =>
          examItem.examId === editingExamId ? { ...examItem, ...updatedExam } : examItem
        )
      );
      setFilteredExamData((prevState) =>
        prevState.map((examItem) =>
          examItem.examId === editingExamId ? { ...examItem, ...updatedExam } : examItem
        )
      );
  
      setEditingExamId(null); // Clear the editing state
    } catch (error) {
      console.error('Error updating exam data:', error);
      setErrorMessage('Unable to update exam data. Please try again later.');
    }
  };
  

  // Cancel editing
  const handleCancel = () => {
    setEditingExamId(null); // Cancel edit mode
  };

  const updateExamData = async (franchiseId, examId, payload) => {
    const url = `/franchises/${franchiseId}/exam-data/${examId}`;
    console.log('API URL:', url); // Log the URL for debugging
    
    try {
      const response = await fetch(url, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      });
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.message || 'Error updating exam data.');
      }
      return data;
    } catch (error) {
      throw new Error(error.message || 'Failed to update exam data.');
    }
  };
  
  

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Exam Data</h1>

      {errorMessage ? (
        <p style={styles.error}>{errorMessage}</p>
      ) : (
        <>
          {/* Franchise filter dropdown */}
          <div style={styles.filterContainer}>
            <label style={styles.filterLabel}>Select Franchise:</label>
            <select
              value={selectedFranchise}
              onChange={handleFranchiseChange}
              style={styles.filterSelect}
            >
              <option value="">All Franchises</option>
              {franchiseNames.map((franchise, index) => (
                <option key={index} value={franchise}>
                  {franchise}
                </option>
              ))}
            </select>
          </div>

          {filteredExamData.length > 0 ? (
            <div style={styles.tableContainer}>
              <table style={styles.table}>
                <thead>
                  <tr>
                    <th style={styles.th}>Franchise Name</th>
                    <th style={styles.th}>Location</th>
                    <th style={styles.th}>Exam Name</th>
                    <th style={styles.th}>Date</th>
                    <th style={styles.th}>Duration (minutes)</th>
                    <th style={styles.th}>Status</th>
                    <th style={styles.th}>Actions</th> {/* Actions column for edit and delete */}
                  </tr>
                </thead>
                <tbody>
                  {filteredExamData.map((exam, index) => (
                    <tr key={index} style={styles.tr}>
                      <td style={styles.td}>{exam.franchiseName}</td>
                      <td style={styles.td}>{exam.location}</td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <input
                            type="text"
                            name="examName"
                            value={editingData.examName}
                            onChange={handleChange}
                            style={styles.input}
                          />
                        ) : (
                          exam.examName
                        )}
                      </td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <input
                            type="date"
                            name="date"
                            value={editingData.date}
                            onChange={handleChange}
                            style={styles.input}
                          />
                        ) : (
                          exam.date
                        )}
                      </td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <input
                            type="number"
                            name="durationInMinutes"
                            value={editingData.durationInMinutes}
                            onChange={handleChange}
                            style={styles.input}
                          />
                        ) : (
                          exam.duration
                        )}
                      </td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <select
                            name="status"
                            value={editingData.status}
                            onChange={handleChange}
                            style={styles.input}
                          >
                            <option value="completed">Completed</option>
                            <option value="inprogress">In Progress</option>
                            <option value="absent">Absent</option>
                          </select>
                        ) : (
                          exam.status
                        )}
                      </td>
                      <td style={styles.td}>
                        {editingExamId === exam.examId ? (
                          <>
                            <button onClick={handleSave} style={styles.editButton}>
                              Save
                            </button>
                            <button onClick={handleCancel} style={styles.cancelButton}>
                              Cancel
                            </button>
                          </>
                        ) : (
                          <>
                            <button onClick={() => handleEditClick(exam)} style={styles.editButton}>
                              Edit
                            </button>
                            <button onClick={() => handleDelete(exam.examId, exam.franchiseId)} style={styles.deleteButton}>
                              Delete
                            </button>
                          </>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p style={styles.noData}>No exam data available for the selected franchise.</p>
          )}
        </>
      )}
    </div>
  );
};

const styles = {
  // ... your existing styles here
  input: {
    padding: '8px',
    fontSize: '1rem',
    width: '100%',
  },
  cancelButton: {
    padding: '5px 10px',
    backgroundColor: '#ffc107',
    color: 'white',
    border: 'none',
    cursor: 'pointer',
    marginLeft: '10px',
  },
};

export default ExamData;
